import * as C from './core.js';
import {BRAND} from './config.js';
import {Backend,LocalStore,configured,validateAttachment} from './persistence.js';
import {PARTS,GUIDES,SOURCES} from './content.js';
import {catalog,choices} from './catalog.js';
import {landingPage} from './landing.js';
import {partsLibraryPage,mountPartsLibrary} from './parts-library.js';
import {INFO_ROUTES,infoPage,helpContent,feedbackForm} from './info-pages.js';
import {mountLanding} from './interactions.js';
import {vehicleArt} from './vehicle-art.js';
import {mountMobileNavigation} from './mobile-nav.js';
import {effectivePreferences,distanceText,distanceFromInput,savePreferences} from './reminder-preferences.js';
const $=s=>document.querySelector(s);
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatMoney=(minor,currency)=>new Intl.NumberFormat(undefined,{style:'currency',currency}).format(minor/100);
const moneyInput=s=>{if(!/^\d+(\.\d{1,2})?$/.test(s))throw Error('Enter a cost with at most two decimal places.');return Math.round(Number(s)*100);};
let state=C.blank(),mode='local',store=null,cloud=new Backend(),busy=false,loaded=false,lastCloudLoad='',explorerCleanup=null,landingCleanup=null,navigationCleanup=null,toastTimer=null,photoUrls=[];
const routes=[['dashboard','◫','Dashboard'],['vehicles','▱','My Garage'],['schedule','◷','Maintenance'],['history','≡','Service history'],['parts','◇','Car Parts'],['explorer','◎','Car explorer'],['guides','▤','Guides'],['expenses','▥','Expenses'],['reminders','◎','Reminders'],['settings','⚙','Settings'],['help','?','Help & Feedback']];
const selected=()=>state.vehicles.find(v=>v.id===state.selectedVehicleId&&!v.archived)||state.vehicles.find(v=>!v.archived);
const activeTasks=v=>state.tasks.filter(t=>t.vehicleId===v?.id&&(!t.templateId||C.applicable(C.TASKS.find(x=>x.id===t.templateId)||{applicability:'all'},v)));
const records=v=>state.services.filter(s=>s.vehicleId===v?.id).sort((a,b)=>b.date.localeCompare(a.date));
const heading=(title,sub,actions='')=>`<div class="heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;
const button=(label,action,extra='',kind='primary')=>`<button class="button ${kind==='primary'?'':esc(kind)}" data-action="${action}" ${extra}>${label}</button>`;
const badge=status=>`<span class="badge ${status.toLowerCase().replaceAll(' ','-')}">${status==='Overdue'?'!':status==='Due soon'?'◷':'·'} ${esc(status==='Due soon'?'Due':status)}</span>`;
const formField=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const selectField=(label,name,options,value,attrs='')=>`<label>${label}<select name="${name}" ${attrs}>${options.map(o=>{const [val,text]=Array.isArray(o)?o:[o,o];return `<option value="${esc(val)}" ${String(val)===String(value)?'selected':''}>${esc(text)}</option>`;}).join('')}</select></label>`;
const checkField=(label,name,checked=false)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
const textArea=(label,name,value='',attrs='')=>`<label class="full">${label}<textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;
const sourceLink=id=>{const s=SOURCES[id];return `<a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`;};
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}

async function enter(next='local'){
 if(busy)return;try{busy=true;const nextStore=next==='cloud'?cloud:new LocalStore(next);const s=await nextStore.load();mode=next;store=nextStore;state=s;loaded=true;if(next==='cloud')lastCloudLoad=new Date().toLocaleTimeString();sessionStorage.setItem('venusdrive.mode',mode);history.pushState(null,'','#'+(s.vehicles.some(v=>!v.archived)?'dashboard':'vehicles'));await render();return true;}catch(e){toast(e.message);return false;}finally{busy=false;}
}
async function commit(next,message){if(busy)throw Error('A save is already in progress.');busy=true;try{await store.save(next);state=next;toast(message|| (mode==='cloud'?'Saved to your account.':'Saved in this browser.'));}finally{busy=false;}}
function modal(title,body,onSubmit=null){const previous=document.activeElement,d=$('#modal');d.onclose=()=>{const target=previous?.isConnected?previous:$('#main');if(target){target.tabIndex=target.tabIndex<0?-1:target.tabIndex;target.focus({preventScroll:true});}};d.onclick=null;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="dialog-close" aria-label="Close dialog" type="button">×</button></div>${onSubmit?'<form class="form-grid">':''}${body}${onSubmit?'<p class="form-error full" role="alert"></p><div class="form-actions"><button type="button" class="button secondary" data-cancel>Cancel</button><button class="button" type="submit">Save</button></div></form>':''}`;
 d.querySelector('.dialog-close').onclick=()=>d.close();d.querySelector('[data-cancel]')?.addEventListener('click',()=>d.close());
 if(onSubmit)d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const submit=form.querySelector('[type=submit]');submit.disabled=true;form.setAttribute('aria-busy','true');const originalLabel=submit.textContent;submit.textContent='Saving…';form.querySelector('.form-error').textContent='';try{await onSubmit(new FormData(form),form);d.close();render();}catch(err){form.querySelector('.form-error').textContent=err.message;}finally{submit.disabled=false;submit.textContent=originalLabel;form.setAttribute('aria-busy','false');}};
 if(!d.open)d.showModal();return d;
}
function confirmAction(title,message,fn,phrase='Confirm'){const d=modal(title,`<p class="full">${esc(message)}</p>${formField('Type '+phrase+' to continue','confirmation','','text','required autocomplete="off"')}`,async f=>{if(f.get('confirmation')!==phrase)throw Error('Type '+phrase+' exactly.');await fn();});d.querySelector('[type=submit]').textContent=phrase;}
function landing(){return landingPage(configured());}
function emptyVehicle(){return `<div class="card empty"><div class="empty-icon">▱</div><h2>Your garage starts here.</h2><p>Add your first vehicle, enter its current mileage, then choose the maintenance you want to track.</p>${button('＋ Add vehicle','add-vehicle')}</div>`;}
function taskRows(v,limit=100){const sorted=activeTasks(v).map(t=>({t,d:C.due(t,v,state.services,effectivePreferences(state,v))})).sort((a,b)=>['Overdue','Due soon','History unknown','Upcoming'].indexOf(a.d.status)-['Overdue','Due soon','History unknown','Upcoming'].indexOf(b.d.status));return sorted.slice(0,limit).map(({t,d})=>`<div class="task-row"><div class="task-icon">${d.status==='Overdue'?'!':'◷'}</div><div class="task-body"><button class="text-button task-title" data-action="task-detail" data-id="${t.id}">${esc(t.name)}</button><small>${d.nextKm!=null?'At '+C.displayDistance(d.nextKm,v.unit)+' '+v.unit:''}${d.nextKm!=null&&d.nextDate?' or ':''}${d.nextDate||''}${!d.nextDate&&d.nextKm==null?'Add a baseline to calculate what’s next.':''}</small>${d.partial?'<p class="form-note">One baseline is missing; only the known threshold is shown.</p>':''}${d.snoozed?`<p class="form-note">Notification snoozed until ${esc(t.snoozedUntil)}. Due thresholds unchanged.</p>`:''}</div>${badge(d.status)}</div>`).join('')||'<p>No maintenance intervals yet. Add them from your owner’s manual.</p>';}
function dashboard(){
 const v=selected();
 if(!v)return heading('Welcome to your garage.','A thoughtful routine starts with one vehicle.')+emptyVehicle();
 const tasks=activeTasks(v),statuses=tasks.map(t=>C.due(t,v,state.services,effectivePreferences(state,v))),rec=records(v);
 const old=(Date.parse(C.today())-Date.parse(v.mileageUpdated))/86400000>effectivePreferences(state,v).staleDays;
 return heading('Your garage. All in view.','A clear view of your vehicle, its mileage, and the next step.',button('＋ Add vehicle','add-vehicle','','secondary')+button('Update mileage','mileage','','secondary')+button('Record service','service'))+
 `<div class="dashboard-grid"><div>
   <section class="vehicle-summary card"><div class="vehicle-summary-copy"><span class="eyebrow">YOUR SELECTED VEHICLE</span><h2>${esc(v.nickname||v.make+' '+v.model)}</h2><p>${v.year} ${esc(v.make)} ${esc(v.model)} · ${esc(v.powertrain)}</p></div><div class="vehicle-mileage"><span class="eyebrow">CURRENT MILEAGE</span><strong class="reading tabular">${C.displayDistance(v.odometerKm,v.unit)} <small>${v.unit}</small></strong><span class="last-update">Last updated ${esc(v.mileageUpdated)}</span>${button('Update mileage','mileage','','secondary')}</div></section>
   ${nextAction(v)}${old?`<div class="notice warning spaced">Your mileage is getting out of date. ${button('Update reading','mileage','','secondary')}</div>`:''}
   <div class="stats">${[['Overdue',statuses.filter(s=>s.status==='Overdue').length,'Needs attention'],['Due soon',statuses.filter(s=>s.status==='Due soon').length,'Plan ahead'],['Recorded visits',rec.length,'History kept']].map(([label,n,note])=>`<div class="stat"><small><i class="dot"></i>${label}</small><strong>${n}</strong><small>${note}</small></div>`).join('')}</div>
   <section class="card"><div class="row between"><h2>Upcoming maintenance</h2><a href="#schedule">View schedule</a></div>${taskRows(v,4)}${!tasks.length?button('Configure maintenance','task','','secondary'):''}</section>
 </div><div>
   <section class="card"><div class="row between"><h2>Recent care</h2><a href="#history">View all</a></div>${rec.slice(0,3).map(s=>`<div class="timeline-item"><h3>${esc(s.taskIds.map(id=>state.tasks.find(t=>t.id===id)?.name||'Service').join(', '))}</h3><small>${s.date} · ${C.displayDistance(s.odometerKm,v.unit)} ${v.unit}</small><div><small>${esc(s.method)} · ${formatMoney(s.costMinor,s.currency)}</small></div></div>`).join('')||'<p>Your completed services will appear here.</p>'}</section>
   <section class="card spaced"><div class="row between"><h2>Actual spending</h2><a href="#expenses">Details</a></div>${totals(rec)}</section>${reminderPanel(v)}
 </div></div>`;
}
function reminderPanel(v){const active=activeTasks(v).filter(t=>C.due(t,v,state.services,effectivePreferences(state,v)).notify);return '<section class="card spaced"><h2>In-app reminders</h2>'+ (active.length?active.map(t=>'<div class="task-row"><button class="text-button" data-action="task-detail" data-id="'+t.id+'">'+esc(t.name)+'</button>'+badge(C.due(t,v,state.services,effectivePreferences(state,v)).status)+'</div>').join(''):'<p>No active maintenance notifications. Snoozed and disabled reminders stay off this list.</p>')+'</section>';}
function totals(rs){const groups=C.spending(rs,'currency');return groups.length?[...new Set(rs.map(r=>r.currency))].map(cur=>`<div class="row between"><span>${cur}</span><h2 class="tabular">${formatMoney(rs.filter(r=>r.currency===cur).reduce((n,r)=>n+r.costMinor,0),cur)}</h2></div>`).join(''):'<p>No expenses recorded yet. Your actual service costs will appear here.</p>';}
function vehiclePage(){return heading('Room for every journey.','Keep vehicles and their histories separate.',button('＋ Add vehicle','add-vehicle'))+(state.vehicles.length?`<div class="list-grid">${state.vehicles.map(v=>`<article class="card list-card"><div class="row between"><div class="task-icon">▱</div><span class="badge">${v.archived?'Archived':selected()?.id===v.id?'Selected':'In your garage'}</span></div><h2 class="spaced">${esc(v.nickname||v.make+' '+v.model)}</h2><p>${v.year} ${esc(v.make)} ${esc(v.model)}<br>${esc(v.powertrain)}${v.engine?' · '+esc(v.engine):''}<br>${C.displayDistance(v.odometerKm,v.unit)} ${v.unit}</p>${vehiclePhoto(v)}<div class="actions">${!v.archived?button('Select','select-vehicle',`data-id="${v.id}"`,'secondary'):''}<button class="text-button" data-action="edit-vehicle" data-id="${v.id}">Edit</button><button class="text-button" data-action="archive" data-id="${v.id}">${v.archived?'Restore':'Archive'}</button></div></article>`).join('')}</div>`:emptyVehicle());}
function schedule(){const v=selected();if(!v)return heading('A routine that fits your car.','Add a vehicle before configuring intervals.')+emptyVehicle();return heading('A routine that fits your car.','Intervals come from your manual or your choices. Nothing is assumed.',button('＋ Add maintenance','task'))+`<div class="notice">Tasks are due when either threshold is reached. Unknown service history stays unknown until you enter a baseline or record a service. Past records are preserved when intervals change.</div><section class="card"><h2>${esc(v.year+' '+v.make+' '+v.model)}</h2><p>${esc([v.engine,v.trim,v.transmission,v.drivetrain].filter(Boolean).join(' · ')||'Configuration details not supplied. Edit your vehicle to add what you know.')}</p><p class="form-note">${v.catalogSource?'Vehicle selection source: '+esc(v.catalogSource.url)+' · retrieved '+esc(v.catalogSource.retrieved):'Manually entered vehicle. No engine, schedule or compatibility has been inferred.'}</p>${taskRows(v)}</section><p class="form-note spaced">Powertrain: ${esc(v.powertrain)}. Tasks that require confirmed equipment appear only after confirmation in Edit vehicle. Inapplicable saved tasks stay in history but are paused here.</p>`;}
function historyPage(){const v=selected();if(!v)return heading('Every service has a story.','Keep a clear record of the care your car receives.')+emptyVehicle();return heading('Every service, remembered.','One visit can complete several tasks. Its cost is counted once.',button('Export CSV','csv','','secondary')+button('＋ Record service','service'))+`<div class="filters"><input id="history-search" aria-label="Search service history" placeholder="Search tasks, notes or shop…"><select id="history-method" aria-label="Service method"><option value="">DIY & mechanic</option><option>DIY</option><option>Mechanic</option></select></div><div id="history-results">${historyRows(records(v))}</div>`;}
function historyRows(rs){return rs.length?`<section class="card"><div class="table-wrap"><table><thead><tr><th>Date & mileage</th><th>Work completed / expand for details</th><th>Service</th><th>Cost</th><th>Actions</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.date}<br><small>${C.displayDistance(r.odometerKm,selected().unit)} ${selected().unit}</small></td><td><details class="service-expand"><summary>${esc(r.taskIds.map(id=>state.tasks.find(t=>t.id===id)?.name||id).join(', '))}</summary><div class="service-notes"><dl><dt>Shop</dt><dd>${esc(r.shop||'Not supplied')}</dd><dt>Parts used</dt><dd>${esc(r.parts||'Not supplied')}</dd><dt>Category</dt><dd>${esc(r.category||'Other')}</dd></dl>${r.notes?`<p>${esc(r.notes)}</p>`:''}${r.items?.length?`<p>Included in visit total:<br>${r.items.map(i=>esc(i.name)+' — '+formatMoney(i.costMinor,r.currency)).join('<br>')}</p>`:''}<p>Visit total counted once. Completed tasks each update their own reminder.</p></div></details></td><td>${esc(r.method)}<br><small>${esc(r.shop)}</small></td><td class="tabular">${formatMoney(r.costMinor,r.currency)}</td><td><button class="text-button" data-action="service" data-id="${r.id}">Edit</button> <button class="text-button danger" data-action="delete-service" data-id="${r.id}">Delete</button>${(r.attachments||[]).map((a,i)=>`<br><button class="text-button" data-action="attachment" data-id="${r.id}" data-index="${i}">▤ ${esc(a.name)}</button>`).join('')}</td></tr>`).join('')}</tbody></table></div></section>`:'<div class="card empty"><h2>No services to show yet.</h2><p>Record DIY work or a mechanic visit when it’s completed.</p></div>';}
function partsPage(){return heading('Explore car parts.','Choose a component, see it clearly, and understand where it usually fits.')+partsLibraryPage(esc);}
function guidesPage(){return heading('A good place to start.','Simple, careful guidance for the everyday driver.')+`<div class="urgent">Urgent symptoms are different from routine care. Reduced braking, smoke, fuel leaks or overheating warrant stopping safely and seeking professional help. VenusDrive does not diagnose faults.</div><div class="filters spaced"><input id="guide-search" type="search" placeholder="Search tire pressure, coolant, wipers…" aria-label="Search maintenance guides"></div><div id="guide-results" class="list-grid guides-grid">${guideTiles(GUIDES)}</div>`;}
function guideTiles(gs){return gs.map(g=>`<article class="card part-tile guide-tile"><div class="eyebrow">${esc(g.difficulty)}</div><h2>${esc(g.title)}</h2><p>${esc(g.why)}</p><small class="guide-duration">Estimated ${esc(g.minutes)}</small><div class="actions"><button class="text-button" data-action="guide" data-id="${g.id}">Read guide</button><a href="#explorer/${g.partId}" class="text-button">Find the part</a></div></article>`).join('')||'<p>No matching guides yet. Try a broader term.</p>';}
function expensesPage(){return heading('Know where your care goes.','Actual recorded expenses. Each currency stays separate.')+`<div class="filters">${selectField('Vehicle','expenseVehicle',[['','All vehicles'],...state.vehicles.map(v=>[v.id,`${v.year} ${v.make} ${v.model}`])],selected()?.id||'','id="expense-vehicle"')}${selectField('View by','group',['month','year','category','method','vehicle'],'month','id="expense-group"')}${selectField('Currency','currency',[['','All currencies'],...new Set(state.services.map(s=>s.currency))],'','id="expense-currency"')}${formField('From','from','','date','id="expense-from"')}${formField('To','to','','date','id="expense-to"')}</div><div id="expense-results" role="region" aria-label="Filtered spending" aria-live="polite"></div>`;}
function renderExpenses(){const vehicle=$('#expense-vehicle').value,cur=$('#expense-currency').value,group=$('#expense-group').value,from=$('#expense-from').value,to=$('#expense-to').value;const rs=state.services.filter(s=>(!vehicle||s.vehicleId===vehicle)&&(!cur||s.currency===cur)&&(!from||s.date>=from)&&(!to||s.date<=to));const groups=C.spending(rs,group);const max=Math.max(1,...groups.map(x=>x.costMinor));$('#expense-results').innerHTML=`<div class="dashboard-grid"><section class="card"><h2>Spending by ${esc(group)}</h2>${groups.length?groups.map(x=>{const name=group==='vehicle'?state.vehicles.find(v=>v.id===x.label)?.nickname||state.vehicles.find(v=>v.id===x.label)?.model||x.label:x.label;return `<div class="spend-line"><span class="spend-label">${esc(name)}</span><div class="bar-wrap"><div class="bar" style="width:${x.costMinor/max*100}%"></div></div><strong>${formatMoney(x.costMinor,x.currency)}</strong></div>`;}).join(''):'<p>No recorded expenses for these filters.</p>'}<p class="form-note">Category totals use each visit’s primary category. Itemized costs are included within the visit total, never added again.</p></section><section class="card mint"><h2>Total recorded</h2>${totals(rs)}<a href="#history">Open the underlying service records</a></section></div>`;}
function settings(){return heading('Make room for your routine.','Storage, reminders, and account preferences.')+`<div class="settings-grid"><section class="card"><h2>Your workspace</h2><div class="setting"><strong>${mode==='demo'?'Separate demo mode':mode==='cloud'?'Supabase account':'Browser-local garage'}</strong><p>${mode==='cloud'?'Data is saved to your account when a save succeeds. Refresh to load another device’s changes.':mode==='demo'?'Sample records are isolated from your own browser-local data.':'Data stays in this browser on this device. It does not automatically sync. Clearing browser storage removes it. Browser storage is not private account security.'}</p></div><div class="setting"><strong>Attachments</strong><p>JPG, PNG and PDF up to 1 MB each. Browser workspaces have a 4 MB total serialized-data limit. Cloud files use a private receipts bucket. Downloads are included in account export.</p></div><div class="actions">${button('Export all data','export','','secondary')}${mode==='demo'?button('Reset demo','reset-demo','','secondary'):''}${button(mode==='demo'?'Open my local garage':'Try separate demo',mode==='demo'?'enter-local':'demo','','secondary')}${mode==='cloud'?button('Refresh cloud data','refresh','','secondary'):''}</div></section><section class="card"><h2>In-app reminders</h2>${preferencesForm()}<p class="form-note spaced">Email and push reminders are not configured. No email subscription or push delivery is implied.</p></section><section class="card"><h2>Cloud accounts</h2><p>${configured()?'Supabase connection configured. Sign in to use your private cloud workspace.': 'Cloud accounts are not available in this installation yet. Your local workspace remains available on this browser.'}</p><div class="actions"><a class="button secondary" href="#signin">Sign in</a><a class="text-button" href="#signup">Create account</a>${mode==='cloud'?button('Sign out','signout','','secondary'):''}</div><p class="form-note spaced">${mode==='cloud'?esc(cloud.user?.email):'No fake sign-in or background synchronization.'}</p>${mode==='cloud'?'<button class="text-button danger" data-action="delete-account">Delete account and private data</button>':''}</section><section class="card lavender"><h2>Built to grow carefully.</h2><p>Vehicle selection includes 15,599 supplied make/year/model rows across 57 brands, covering collected years from 1984–2027. Coverage is incomplete. Engines, schedules and fitment are not inferred.</p><p>Parts library: ${PARTS.length} introductory components. Guides: ${GUIDES.length}. Explorer: generic educational vehicle, not a vehicle-specific repair diagram.</p></section></div>`;}
function authPage(route){if(route==='verify')return verificationPage();const recovery=route==='recovery',signup=route==='signup',forgot=route==='forgot';return `<div class="landing"><a href="#home" class="brand"><img src="${BRAND.logo}" alt="VD">VenusDrive</a></div><main id="main" class="auth"><section class="card"><div class="eyebrow">YOUR VENUSDRIVE ACCOUNT</div><h1>${recovery?'Set a new password':signup?'A home for your car’s care.':forgot?'Find your way back.':'Welcome back.'}</h1><p>${recovery?'Use the recovery link sent by your configured provider.':signup?'Keep your vehicles and service records together.':forgot?'Request an account recovery email.':'Sign in to your private cloud workspace.'}</p>${!configured()?'<div class="notice warning">Cloud sign-in is not available in this installation yet. You can use the local workspace; it will not sync across devices.</div>':''}<form id="auth-form">${!recovery?formField('Email address','email','','email','autocomplete="email" required'):''}${!forgot?formField(signup||recovery?'New password (at least 12 characters)':'Password','password','','password',`autocomplete="${signup||recovery?'new-password':'current-password'}" minlength="${signup||recovery?12:1}" required`):''}<p class="form-error" role="alert"></p><button class="button" type="submit" ${!configured()?'disabled':''}>${recovery?'Update password':signup?'Create account':forgot?'Request recovery email':'Sign in'}</button><p id="auth-result" role="status" class="form-note"></p></form></section><nav><a href="#signin">Sign in</a><a href="#signup">Create account</a><a href="#forgot">Forgot password?</a><a href="#verify">Verify email / resend link</a></nav><button class="text-button" data-action="enter-local">Continue with browser-local storage</button></main>`;}

function shell(route,body){return `<div class="shell"><aside class="sidebar" id="garage-navigation"><button class="mobile-nav-close" type="button" data-nav-close>Close navigation</button><a href="#home" class="brand"><img src="${BRAND.logo}" alt="VD">VenusDrive</a><nav aria-label="Main navigation">${routes.map(([r,icon,label])=>`<a class="nav-link ${route===r?'active':''}" ${route===r?'aria-current="page"':''} href="#${r}"><span class="nav-icon" aria-hidden="true">${navIcon(r)}</span>${label}</a>`).join('')}</nav><div class="sidebar-note"><strong>Care, at your own pace.</strong>Small checks today.<br>More confidence tomorrow.<br><a href="#guides">Learn something new</a></div></aside><button class="nav-backdrop" type="button" data-nav-backdrop aria-label="Close navigation" tabindex="-1" hidden></button><div class="workspace"><header class="topbar"><div class="row"><button class="mobile-toggle" data-action="menu" aria-label="Open navigation" aria-controls="garage-navigation" aria-expanded="false">☰</button><small class="top-label">Your garage / ${esc(routes.find(x=>x[0]===route)?.[2]||'Explore')}</small></div><div class="row"><select id="vehicle-switcher" aria-label="Selected vehicle"><option value="">${state.vehicles.some(v=>!v.archived)?'Choose vehicle':'No vehicles yet'}</option>${state.vehicles.filter(v=>!v.archived).map(v=>`<option value="${v.id}" ${selected()?.id===v.id?'selected':''}>${esc(v.nickname||`${v.year} ${v.make} ${v.model}`)}</option>`).join('')}</select><button class="button secondary add-vehicle-control" data-action="add-vehicle" aria-label="Add vehicle">＋ <span>Add vehicle</span></button><span class="avatar" title="${mode==='demo'?'Demo':mode==='cloud'?'Cloud account':'Local workspace'}">${mode==='demo'?'DE':mode==='cloud'?'VD':'LO'}</span></div></header><main id="main" class="content"><div class="notice ${mode==='demo'?'warning':''}">${mode==='demo'?'Demo mode — sample records are separate from your data.':mode==='cloud'?'Cloud workspace — loaded '+esc(lastCloudLoad)+'. Refresh to see other-device changes.':'Local garage — saved only in this browser. No account or automatic device sync.'} <button class="text-button" data-action="${mode==='demo'?'enter-local':mode==='cloud'?'refresh':'demo'}">${mode==='demo'?'Open my garage':mode==='cloud'?'Refresh':'Try demo'}</button></div>${body}</main></div></div>`;}

async function render(){navigationCleanup?.();navigationCleanup=null;landingCleanup?.();landingCleanup=null;for(const url of photoUrls)URL.revokeObjectURL(url);photoUrls=[];explorerCleanup?.();explorerCleanup=null;const [route='home',item]=location.hash.slice(1).split('?')[0].split('/');document.title=`${routes.find(x=>x[0]===route)?.[2]||'Care for your journey'} · ${BRAND.name}`;
 if(INFO_ROUTES.includes(route)){$('#app').innerHTML=infoPage(route,BRAND);bind();bindFeedback();return;}
 if(['signin','signup','forgot','recovery','verify'].includes(route)){$('#app').innerHTML=authPage(route);bind();$('#auth-form').onsubmit=e=>authSubmit(e,route);return;}
 if(!route||route==='home'){$('#app').innerHTML=landing();bind();landingCleanup=mountLanding($('#app'));return;}
 if(!loaded){try{mode=sessionStorage.getItem('venusdrive.mode')==='demo'?'demo':'local';store=new LocalStore(mode);state=await store.load();loaded=true;}catch(e){$('#app').innerHTML=landing();toast(e.message);bind();return;}}
 const pages={dashboard,vehicles:vehiclePage,schedule,history:historyPage,parts:partsPage,guides:guidesPage,expenses:expensesPage,settings,reminders:remindersPage,help:helpPage,explorer:()=>heading('A closer look. A clearer picture.','Choose a part. See what it looks like. Understand what it does.')+'<div id="explorer-root" aria-busy="true"><p><span class="loading-pulse" aria-hidden="true"></span>Loading the educational explorer…</p></div>'};
 $('#app').innerHTML=shell(route,(pages[route]||dashboard)());bind();navigationCleanup=mountMobileNavigation($('.shell'));
 if(route==='vehicles')loadVehiclePhotos();
 if(route==='expenses'){renderExpenses();document.querySelectorAll('.filters input,.filters select').forEach(e=>e.onchange=renderExpenses);}
 if(route==='explorer')try{const {mount}=await import('./explorer.js');if(location.hash.slice(1).split('?')[0].split('/')[0]==='explorer')explorerCleanup=mount($('#explorer-root'),{partId:item,vehicle:selected(),onGuide:openGuide,onPart:partDetail,parts:PARTS,esc});$('#explorer-root')?.setAttribute('aria-busy','false');}catch(e){if(!$('#explorer-root'))return;$('#explorer-root').setAttribute('aria-busy','false');$('#explorer-root').innerHTML='<div class="notice warning">The visual explorer could not load. Use the Parts library for text explanations, and reload to retry.</div>';}
 if(route==='parts')explorerCleanup=mountPartsLibrary($('#parts-library-root'),{esc});
 if(route==='guides')$('#guide-search').oninput=e=>{const q=e.target.value.toLowerCase();$('#guide-results').innerHTML=guideTiles(GUIDES.filter(g=>(g.title+' '+g.why+' '+g.partId).toLowerCase().includes(q)));};
 if(route==='history'&&$('#history-search')){const update=()=>{const q=$('#history-search').value.toLowerCase(),method=$('#history-method').value;$('#history-results').innerHTML=historyRows(records(selected()).filter(r=>(!method||r.method===method)&&JSON.stringify({...r,taskNames:r.taskIds.map(id=>state.tasks.find(t=>t.id===id)?.name)}).toLowerCase().includes(q)));};$('#history-search').oninput=update;$('#history-method').onchange=update;}
 bindPreferences();bindFeedback();

}
async function authSubmit(e,route){e.preventDefault();const form=e.target,f=new FormData(form),b=form.querySelector('[type=submit]');b.disabled=true;form.querySelector('.form-error').textContent='';try{if(route==='verify'){await cloud.resendVerification(f.get('email'));$('#auth-result').textContent='Verification request accepted. Check your inbox if an account is eligible. Delivery is not confirmed here.';}else if(route==='signin'){await cloud.signIn(f.get('email'),f.get('password'));state=C.blank();loaded=false;mode='local';await enter('cloud');}else if(route==='signup'){const result=await cloud.signUp(f.get('email'),f.get('password'));$('#auth-result').textContent=result?.access_token?'Account created. Email verification is not enabled on this installation.':'Account request accepted. Check your email for the verification link if an account was created. Delivery is not confirmed here.';form.reset();}else if(route==='forgot'){await cloud.recover(f.get('email'));$('#auth-result').textContent='Recovery request accepted. If this address has an account, check its inbox. Delivery is not confirmed here.';}else{await cloud.password(f.get('password'));toast('Password updated by Supabase.');location.hash='signin';}}catch(err){form.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}}
function bind(){
 $('#app').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{await action(b.dataset.action,b.dataset);}catch(err){toast(err.message);}};
 $('#vehicle-switcher')?.addEventListener('change',async e=>{if(!e.target.value)return;try{await commit({...state,selectedVehicleId:e.target.value},'Vehicle selected.');render();}catch(err){toast(err.message);}});
}
async function action(name,data={}){
 if(name==='start-garage'||name==='open-garage'){
  if(mode==='cloud'&&loaded){history.pushState(null,'','#'+(selected()?'dashboard':'vehicles'));await render();}
  else if(!await enter('local'))return;
  if(name==='start-garage')return vehicleForm();return;
 }
 if(name==='reset-demo'){
  if(mode!=='demo'||!(store instanceof LocalStore))throw Error('Only the separate demo can be reset here.');
  return confirmAction('Reset demo?', 'This replaces only sample demo records. Your own local garage stays unchanged.',async()=>{await commit(C.demoData(),'Demo reset. Your garage was not changed.');},'Reset demo');
 }
 if(name==='enter-local')return enter('local');if(name==='demo')return enter('demo');
 if(name==='menu')return;
 if(name==='add-vehicle'||name==='edit-vehicle')return vehicleForm(data.id);
 if(name==='select-vehicle'){await commit({...state,selectedVehicleId:data.id},'Vehicle selected.');location.hash='dashboard';return render();}
 if(name==='archive'){const v=state.vehicles.find(x=>x.id===data.id);await commit({...state,vehicles:state.vehicles.map(x=>x.id===data.id?{...x,archived:!x.archived}:x),selectedVehicleId:state.selectedVehicleId===data.id?null:state.selectedVehicleId},v.archived?'Vehicle restored.':'Vehicle archived. Its history is preserved.');return render();}
 if(name==='mileage')return mileageForm();if(name==='task')return taskForm(data.id);if(name==='task-detail')return taskDetail(data.id);if(name==='service')return serviceForm(data.id,data.task);
 if(name==='delete-service'){const r=state.services.find(x=>x.id===data.id);return confirmAction('Delete this service?','This removes the visit, its expense and its links to reminders. Remaining history will determine what is due.',async()=>{await commit(C.deleteService(state,data.id),'Service deleted and reminders recalculated.');for(const a of r.attachments||[])try{await store.deleteAttachment(a);}catch{toast('Record deleted. Some cloud receipts could not be removed; retry cleanup before production use.');}},'Delete');}
 if(name==='attachment'){const r=state.services.find(x=>x.id===data.id),a=r.attachments[Number(data.index)];const url=await store.attachment(a);const link=document.createElement('a');link.href=url;link.download=a.name;link.click();if(url.startsWith('blob:'))setTimeout(()=>URL.revokeObjectURL(url),30000);return;}
 if(name==='part-detail')return partDetail(data.id);if(name==='guide')return openGuide(data.id);
 if(name==='csv')return download(C.csvExport(state,selected()?.id),'VenusDrive-service-history.csv','text/csv');
 if(name==='export')return exportAccount();
 if(name==='refresh'){if(mode!=='cloud')return;return confirmAction('Reload cloud data?','This loads the latest saved account version. Close or finish any unsaved form before refreshing.',async()=>{state=await cloud.load();lastCloudLoad=new Date().toLocaleTimeString();toast('Latest cloud snapshot loaded.');},'Reload');}
 if(name==='signout'){await cloud.signOut();loaded=false;mode='local';sessionStorage.removeItem('venusdrive.mode');state=C.blank();location.hash='home';return render();}
 if(name==='delete-account')return confirmAction('Delete your account?','This permanently deletes your account, service data and private receipts. Export your data first. The configured deletion function must succeed before completion is shown.',async()=>{await cloud.deleteAccount();state=C.blank();loaded=false;sessionStorage.removeItem('venusdrive.mode');location.hash='home';toast('Account deleted.');},'DELETE');
}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportAccount(){const copy=structuredClone(state);for(const v of copy.vehicles){if(v.photoAttachment?.path){const u=await cloud.attachment(v.photoAttachment);v.photo=await blobDataURL(await fetch(u).then(r=>r.blob()));URL.revokeObjectURL(u);}}for(const r of copy.services)for(const a of r.attachments||[]){if(a.path){const u=await cloud.attachment(a);const b=await fetch(u).then(r=>r.blob());a.data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(b);});URL.revokeObjectURL(u);}}download(JSON.stringify({exportedAt:new Date().toISOString(),mode,data:copy},null,2),'VenusDrive-data-export.json','application/json');toast('Export prepared with recorded attachments.');}

function mileageForm(){const v=selected();if(!v)throw Error('Add a vehicle first.');modal('Update mileage',`<p class="form-note full">Current: ${C.displayDistance(v.odometerKm,v.unit)} ${v.unit}. Every reading is kept. A lower reading requires an explicit correction reason.</p>${formField('New odometer reading ('+v.unit+')','reading','','number','min="0" step="0.1" required')}${formField('Correction reason (if lower)','reason')}`,async f=>{await commit(C.updateMileage(state,v.id,f.get('reading'),v.unit,f.get('reason')));});}
async function vehicleForm(id){const old=state.vehicles.find(v=>v.id===id);const v=old||{year:'',make:'',model:'',powertrain:'unknown',unit:'mi',odometerKm:0,features:{}};let catalogRows=null;const d=modal(old?'Edit vehicle':'Add your vehicle',`${!old?'<p class="form-note full">Start with the details you know. '+(mode==='cloud'?'Saved to your signed-in garage.':'Saved only in this browser, without automatic device sync.')+'</p>':''}${!old?'<details class="full"><summary>Choose from the supplied catalog (optional)</summary><p>Partial make/year/model catalog only. No engine or fitment inference.</p><div id="catalog-selectors">Loading catalog… Manual entry is available below.</div></details>':''}${formField('Year','year',v.year,'number','min="1886" max="'+(new Date().getFullYear()+2)+'" required')}${formField('Make','make',v.make,'text','required maxlength="80"')}${formField('Model','model',v.model,'text','required maxlength="100"')}${selectField('Powertrain','powertrain',C.POWERTRAINS,v.powertrain)}${selectField('Distance unit','unit',['mi','km'],v.unit)}${old?'<p class="form-note">Changing units converts the display of all readings. Stored physical distances and history stay unchanged. Use Update mileage for corrections.</p>':formField('Current odometer reading','reading','','number','min="0" step="0.1" required')}${formField('Nickname (optional)','nickname',v.nickname)}<details class="full"><summary>More vehicle details (optional)</summary><div class="form-grid">${formField('Engine (if known)','engine',v.engine)}${formField('Trim (if known)','trim',v.trim)}${formField('Transmission (if known)','transmission',v.transmission)}${formField('Drivetrain (if known)','drivetrain',v.drivetrain)}${formField('VIN (optional)','vin',v.vin,'text','maxlength="17" autocomplete="off"')}${formField('Vehicle photo (optional, JPG/PNG ≤ 1 MB)','photo','','file','accept="image/jpeg,image/png"')}</div></details><input type="hidden" name="catalogId" value="${esc(v.catalogId||'')}"><details class="full"><summary>Confirm equipment where known</summary><p>Only mark Yes when confirmed by your vehicle documentation. “No / unknown” leaves the corresponding task unconfigured.</p><div class="form-grid">${C.TASKS.filter(t=>t.applicability.startsWith('confirm')).map(t=>selectField(t.name,'feature-'+t.id,[['unknown','No / unknown'],['yes','Yes, confirmed']],v.features?.[t.id]?'yes':'unknown')).join('')}</div></details>`,async(f,form)=>{
  const file=f.get('photo');let photo=v.photo||'',photoAttachment=v.photoAttachment||null,uploadedPhoto=null;if(file?.size){validateAttachment(file);if(!file.type.startsWith('image/'))throw Error('Choose a JPG or PNG vehicle photo.');uploadedPhoto=await store.upload(file,C.uid());if(mode==='cloud'){photoAttachment=uploadedPhoto;photo='';}else photo=uploadedPhoto.data;}
  const next={...v,year:Number(f.get('year')),make:f.get('make').trim(),model:f.get('model').trim(),powertrain:f.get('powertrain'),unit:f.get('unit'),odometerKm:old?v.odometerKm:C.km(f.get('reading'),f.get('unit')),photo,photoAttachment};
  for(const key of ['nickname','engine','trim','transmission','drivetrain','vin'])next[key]=f.get(key).trim();next.vin=next.vin.toUpperCase();
  next.features=Object.fromEntries(C.TASKS.filter(t=>t.applicability.startsWith('confirm')).map(t=>[t.id,f.get('feature-'+t.id)==='yes']));
  const match=catalogRows?.find(r=>r.catalog_id===f.get('catalogId')&&r.make===next.make&&r.year===next.year&&r.model===next.model);next.catalogId=match?.catalog_id||(old&&old.make===next.make&&old.year===next.year&&old.model===next.model?v.catalogId:'');next.catalogSource=match?{url:match.source_url,retrieved:match.retrieved,nhtsaModelId:match.nhtsa_model_id}:next.catalogId?v.catalogSource:null;
  try{await commit(old?C.editVehicle(state,next):C.addVehicle(state,next));if(!old)history.replaceState(null,'','#dashboard');}catch(e){if(uploadedPhoto)await store.deleteAttachment(uploadedPhoto).catch(()=>{});throw e;}if(uploadedPhoto&&v.photoAttachment)await store.deleteAttachment(v.photoAttachment).catch(()=>toast('Vehicle saved. Previous photo cleanup needs a retry.'));
 });
 if(!old)try{catalogRows=await catalog();if(!d.open)return;const target=d.querySelector('#catalog-selectors');target.innerHTML=`<div class="form-grid">${selectField('Catalog make','catalogMake',[['','Choose make'],...choices(catalogRows).makes],'')}${selectField('Catalog year','catalogYear',[['','Choose make first']],'')}${selectField('Catalog model','catalogModel',[['','Choose year first']],'')}</div><p class="form-note">Manual fields remain editable. Configuration details must be supplied by you.</p>`;
 target.querySelector('[name=catalogMake]').onchange=e=>{const make=e.target.value;target.querySelector('[name=catalogYear]').innerHTML='<option value="">Choose year</option>'+choices(catalogRows,make).years.map(y=>`<option>${y}</option>`).join('');target.querySelector('[name=catalogModel]').innerHTML='<option value="">Choose year first</option>';};
 target.querySelector('[name=catalogYear]').onchange=e=>{target.querySelector('[name=catalogModel]').innerHTML='<option value="">Choose model</option>'+choices(catalogRows,target.querySelector('[name=catalogMake]').value,e.target.value).models.map(r=>`<option value="${r.catalog_id}">${esc(r.model)}</option>`).join('');};
 target.querySelector('[name=catalogModel]').onchange=e=>{const row=catalogRows.find(r=>r.catalog_id===e.target.value);if(row){for(const key of ['year','make','model'])d.querySelector(`[name=${key}]`).value=row[key];d.querySelector('[name=catalogId]').value=row.catalog_id;}};
 }catch(e){if(d.open)d.querySelector('#catalog-selectors').textContent=e.message;}
}

function taskForm(id){const v=selected();if(!v)throw Error('Add a vehicle first.');const old=state.tasks.find(t=>t.id===id);const templates=C.TASKS.filter(t=>C.applicable(t,v));const t=old||{name:'',months:'',distanceKm:null,baselineDate:'',baselineKm:null,guidance:'User-defined intervals',reminders:true};
 const d=modal(old?'Edit maintenance interval':'Configure maintenance',`${selectField('Maintenance type','templateId',[['','Custom maintenance'],...templates.map(t=>[t.id,t.name])],t.templateId)}${formField('Task name','name',t.name,'text','required maxlength="100"')}${formField('Interval (months, optional)','months',t.months??'','number','min="1" max="600" step="1"')}${formField('Interval ('+v.unit+', optional)','distance',t.distanceKm!=null?(t.distanceKm/(v.unit==='mi'?1.609344:1)).toFixed(2):'','number','min="0.01" step="0.01"')}${formField('Baseline service date (if known)','baselineDate',t.baselineDate||'','date','max="'+C.today()+'"')}${formField('Baseline odometer ('+v.unit+', if known)','baselineReading',t.baselineKm!=null?(t.baselineKm/(v.unit==='mi'?1.609344:1)).toFixed(2):'','number','min="0" step="0.01"')}<p class="form-note full">Leave unknown history blank. The latest relevant saved service overrides the baseline. Editing intervals never changes your service history.</p>${selectField('Interval guidance','guidance',['User-defined intervals','General guidance'],t.guidance)}${formField('Source / owner’s manual reference','source',t.source||'')}${formField('Operating conditions / notes','conditions',t.conditions||'')}${formField('Advance notice (days)','advanceDays',t.advanceDays??effectivePreferences(state,v).advanceDays,'number','min="0" max="365"')}${formField('Advance notice ('+v.unit+')','advanceDistance',distanceText(t.advanceKm??effectivePreferences(state,v).advanceKm,v.unit),'number','min="0" step="any"')}${checkField('Override workspace / vehicle reminder defaults for this task','overrideReminders',old?.advanceKm!=null||old?.advanceDays!=null)}${checkField('Enable in-app reminders for this task','reminders',t.reminders!==false)}<p class="form-note full">No verified manufacturer schedules are bundled. Enter intervals from your manual. Choosing General guidance does not verify an interval.</p>`,async f=>{
  const template=C.TASKS.find(x=>x.id===f.get('templateId'));if(template&&!C.applicable(template,v))throw Error('This task is not confirmed applicable to the selected vehicle.');
  const next={...t,id:old?.id,vehicleId:v.id,templateId:template?.id||'',partId:template?.partId||'',category:template?.category||'Custom',name:f.get('name').trim(),months:f.get('months')?Number(f.get('months')):null,distanceKm:f.get('distance')?C.km(f.get('distance'),v.unit):null,baselineDate:f.get('baselineDate')||null,baselineKm:f.get('baselineReading')?C.km(f.get('baselineReading'),v.unit):null,guidance:f.get('guidance'),source:f.get('source'),conditions:f.get('conditions'),advanceDays:f.has('overrideReminders')?Number(f.get('advanceDays')):null,advanceKm:f.has('overrideReminders')?distanceFromInput(f.get('advanceDistance'),v.unit,t.advanceKm??effectivePreferences(state,v).advanceKm,distanceText(t.advanceKm??effectivePreferences(state,v).advanceKm,v.unit)):null,reminders:f.has('reminders')};
  if(next.advanceDays<0||next.advanceDays>365||next.advanceKm<0||(next.advanceKm!=null&&!Number.isFinite(next.advanceKm)))throw Error('Reminder advance values must be valid and non-negative.');await commit(C.saveTask(state,next),'Maintenance interval saved. Historical services preserved.');
 });
 d.querySelector('[name=templateId]').onchange=e=>{const temp=C.TASKS.find(x=>x.id===e.target.value);if(temp)d.querySelector('[name=name]').value=temp.name;};
}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id),v=selected();if(!t||!v)return;const d=C.due(t,v,state.services,effectivePreferences(state,v));const explanation=`${d.last?'Last applicable recorded service':'User-entered baseline'}: ${d.baselineDate||'date unknown'}, ${d.baselineKm!=null?C.displayDistance(d.baselineKm,v.unit)+' '+v.unit:'odometer unknown'}. Interval: ${t.distanceKm?C.displayDistance(t.distanceKm,v.unit)+' '+v.unit:''}${t.distanceKm&&t.months?' or ':''}${t.months?t.months+' months':''}. Next due: ${d.nextKm!=null?C.displayDistance(d.nextKm,v.unit)+' '+v.unit:''}${d.nextKm!=null&&d.nextDate?' or ':''}${d.nextDate||''}${d.nextDate&&d.nextKm!=null?', whichever comes first.':'.'} Missing baselines are not assumed.`;
 const dialog=modal(t.name,`${badge(d.status)}<div class="detail-block"><h3>How this was calculated</h3><p>${esc(explanation)}</p><p>${esc(t.guidance)} · ${esc(t.source||'No source supplied')}<br>${esc(t.conditions||'No operating conditions supplied')}</p></div><div class="actions">${button('Record service','service',`data-task="${id}"`)}${button('Edit interval','task',`data-id="${id}"`,'secondary')}${t.partId?`<a class="button secondary" href="#explorer/${t.partId}" data-close-dialog>Locate part</a>`:''}</div><div class="detail-block"><h3>Related guide</h3><button class="text-button" data-action="guide" data-id="${GUIDES.find(g=>g.partId===t.partId)?.id||'professional'}">Read a relevant guide</button></div><div class="detail-block"><h3>Reminder</h3><p>${d.snoozed?'Snoozed until '+esc(t.snoozedUntil)+'.':'Notifications '+(t.reminders===false?'disabled.':'enabled.')} Snoozing does not change the due date or mileage.</p><button class="button secondary" data-snooze>Snooze 7 days</button> <button class="text-button" data-unsnooze>Clear snooze</button></div>`);
 dialog.onclick=async e=>{const b=e.target.closest('[data-action]');if(b){dialog.close();return action(b.dataset.action,b.dataset);}if(e.target.closest('[data-close-dialog]'))dialog.close();if(e.target.matches('[data-snooze],[data-unsnooze]'))try{const date=new Date();date.setUTCDate(date.getUTCDate()+7);await commit(C.saveTask(state,{...t,snoozedUntil:e.target.matches('[data-snooze]')?date.toISOString().slice(0,10):null}),'Reminder preference saved. Due thresholds unchanged.');dialog.close();render();}catch(err){toast(err.message);}};
}

function serviceForm(id,taskId){const v=selected();if(!v)throw Error('Add a vehicle first.');const old=state.services.find(r=>r.id===id);const tasks=old?state.tasks.filter(t=>t.vehicleId===v.id):activeTasks(v);if(!tasks.length)return taskForm();const r=old||{date:C.today(),odometerKm:v.odometerKm,taskIds:taskId?[taskId]:[],costMinor:0,currency:'USD',method:'DIY',items:[],attachments:[]};
 modal(old?'Edit service visit':'Record a service visit',`${formField('Service date','date',r.date,'date','required max="'+C.today()+'"')}${formField('Odometer ('+v.unit+')','reading',(r.odometerKm/(v.unit==='mi'?1.609344:1)).toFixed(2),'number','required min="0" step="0.01"')}<div class="full"><label>Tasks completed in this visit</label><div class="checklist">${tasks.map(t=>checkField(esc(t.name),'task-'+t.id,r.taskIds.includes(t.id))).join('')}</div></div>${selectField('Performed by','method',['DIY','Mechanic'],r.method)}${formField('Shop name (optional)','shop',r.shop)}${formField('Total visit cost','cost',(r.costMinor/100).toFixed(2),'number','min="0" step="0.01" required')}${selectField('Currency','currency',['USD','EUR','GBP','CAD','AUD','INR','BDT','PKR','AED'],r.currency)}${selectField('Primary expense category','category',[...new Set([...tasks.map(t=>t.category),'Other'])],r.category||tasks[0]?.category)}${formField('Parts used (manual, optional)','parts',r.parts)}${textArea('Notes','notes',r.notes)}${textArea('Optional itemized costs: one “description | amount” per line','items',r.items.map(i=>i.name+' | '+(i.costMinor/100).toFixed(2)).join('\n'))}<p class="form-note full">The visit total is the actual expense. Itemized lines are included within it, not additional charges.</p>${formField('Add receipt/photo (JPG, PNG or PDF ≤ 1 MB)','receipt','','file','accept="image/jpeg,image/png,application/pdf"')}<div class="full">${r.attachments.map((a,i)=>checkField('Keep '+esc(a.name),'keep-'+i,true)).join('')}</div>`,async f=>{
  const taskIds=tasks.filter(t=>f.has('task-'+t.id)).map(t=>t.id),items=f.get('items').split('\n').filter(x=>x.trim()).map(line=>{const at=line.lastIndexOf('|');if(at<0)throw Error('Itemized lines must use description | amount.');return {name:line.slice(0,at).trim(),costMinor:moneyInput(line.slice(at+1).trim())};});
  const next={...r,id:old?.id||C.uid(),vehicleId:v.id,date:f.get('date'),odometerKm:C.km(f.get('reading'),v.unit),taskIds,costMinor:moneyInput(f.get('cost')),currency:f.get('currency'),method:f.get('method'),shop:f.get('shop').trim(),category:f.get('category'),parts:f.get('parts').trim(),notes:f.get('notes').trim(),items,attachments:r.attachments.filter((a,i)=>f.has('keep-'+i))};
  C.saveService(state,next);const file=f.get('receipt');let uploaded=null;if(file?.size){validateAttachment(file);uploaded=await store.upload(file,C.uid());next.attachments.push(uploaded);}
  try{await commit(C.saveService(state,next),'Service saved. Reminders and spending recalculated.');}catch(e){if(uploaded)try{await store.deleteAttachment(uploaded);}catch{}throw e;}
  for(const a of r.attachments.filter((a,i)=>!f.has('keep-'+i)))try{await store.deleteAttachment(a);}catch{toast('Service saved. Removed receipt cleanup failed; cloud cleanup needs a retry.');}
 });
}
function partDetail(id){if(PARTS.some(p=>p.id===id))location.hash='explorer/'+id;}
function openGuide(id){const g=GUIDES.find(g=>g.id===id);if(!g)return;const d=modal(g.title,`<span class="badge">${esc(g.difficulty)} · Estimated ${esc(g.minutes)}</span><div class="detail-block"><h3>Why it matters</h3><p>${esc(g.why)}</p><h3>Signs that warrant attention</h3><p>${esc(g.signs)}</p><h3>Tools and supplies</h3><p>${esc(g.tools)}</p></div><div class="detail-block"><h3>Simple steps</h3><ol>${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="urgent">When to stop: ${esc(g.stop)}</div></div><p class="form-note">Follow the exact owner’s manual. Never go underneath a vehicle supported only by a jack. Component images are not repair or access instructions.</p><div class="actions"><a href="#explorer/${g.partId}" class="button secondary" data-close-dialog>Find the part</a>${selected()?button('Record completed work','service'):''}</div><p class="form-note spaced">Supporting source: ${sourceLink(g.source)}</p>`);d.querySelector('[data-close-dialog]').onclick=()=>d.close();d.querySelector('[data-action]')?.addEventListener('click',()=>{d.close();serviceForm();});}
window.addEventListener('hashchange',async()=>{await render();window.scrollTo({top:0,behavior:'instant'});const main=$('#main');if(main){main.tabIndex=-1;main.focus({preventScroll:true});}});
window.addEventListener('storage',e=>{if(store instanceof LocalStore&&e.key===store.key)toast('This workspace changed in another tab. Refresh before saving.');});
async function boot(){try{if(configured()){const result=await cloud.restore();if(result.user){mode='cloud';store=cloud;state=await cloud.load();loaded=true;lastCloudLoad=new Date().toLocaleTimeString();if(result.recovery)location.hash='recovery';else if(location.hash==='#dashboard'&&!state.vehicles.some(v=>!v.archived))location.hash='vehicles';}}}catch(e){toast(e.message);}render();}
boot();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const main=document.querySelector('#main');if(main){main.tabIndex=-1;main.focus();}});

async function blobDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Export could not read an attachment.'));r.readAsDataURL(blob);});}
async function loadVehiclePhotos(){for(const img of document.querySelectorAll('[data-vehicle-photo]')){const v=state.vehicles.find(v=>v.id===img.dataset.vehiclePhoto);try{const url=await store.attachment(v.photoAttachment);if(img.isConnected){photoUrls.push(url);img.src=url;img.hidden=false;}else if(url.startsWith('blob:'))URL.revokeObjectURL(url);}catch{img.insertAdjacentHTML('afterend','<small>Vehicle photo could not load. Refresh to retry.</small>');}}}

function vehiclePhoto(v){return v.photo?'<img src="'+esc(v.photo)+'" alt="'+esc(v.nickname||v.model)+'" style="max-width:100%;height:150px;object-fit:cover;border-radius:12px">':v.photoAttachment?'<img data-vehicle-photo="'+v.id+'" alt="'+esc(v.nickname||v.model)+'" hidden style="max-width:100%;height:150px;object-fit:cover;border-radius:12px">':'';}

document.querySelector('link[rel=canonical]').href=BRAND.domain+'/';

function nextAction(v){const rank={'Overdue':0,'Due soon':1,'History unknown':2,'Upcoming':3};const next=activeTasks(v).map(t=>({t,d:C.due(t,v,state.services,effectivePreferences(state,v))})).sort((a,b)=>rank[a.d.status]-rank[b.d.status]||(a.d.days??Infinity)-(b.d.days??Infinity)||(a.d.remaining??Infinity)-(b.d.remaining??Infinity))[0];if(!next)return '<section class="next-action"><div><span class="section-index">NEXT STEP</span><h3>Set your maintenance intervals.</h3><p>Use your owner’s manual. Unknown service history stays unknown.</p></div>'+button('Configure maintenance','task','','secondary')+'</section>';return '<section class="next-action"><div><span class="section-index">NEXT USEFUL ACTION</span><h3>'+esc(next.t.name)+' <span class="next-status">'+esc(next.d.status)+'</span></h3><p>'+(next.d.status==='History unknown'?'Add a known service baseline to calculate what’s next.':'Next threshold: '+esc(next.d.nextDate||'date not configured')+(next.d.nextKm!=null?' or '+C.displayDistance(next.d.nextKm,v.unit)+' '+v.unit:'')+'.')+'</p></div>'+button('View details','task-detail','data-id="'+next.t.id+'"','secondary')+'</section>';}


function navIcon(route){const paths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',vehicles:'M3 17v-6l2-6h14l2 6v6M3 11h18M5 17v3M19 17v3M6 14h2M16 14h2M3 17h18',schedule:'M4 5h16v16H4zM4 10h16M8 2v6M16 2v6M8 14h3M8 17h6',history:'M3 5v5h5M3 10a9 9 0 1 1 1 8M12 7v6l4 2',parts:'M12 2l9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10M7 4.8l10 5.5',explorer:'M12 2v4M12 18v4M2 12h4M18 12h4M12 5a7 7 0 1 0 0 14 7 7 0 0 0 0-14M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',guides:'M12 5Q7 2 2 4v16q5-2 10 1 5-3 10-1V4q-5-2-10 1zM12 5v16',expenses:'M3 3v18h19M7 17v-5M12 17V7M17 17V3',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="square" stroke-linejoin="miter" aria-hidden="true"><path d="'+(paths[route]||paths.dashboard)+'"/></svg>';}

function preferencesForm(scope='global'){const v=selected(),unit=v?.unit||'km',prefs=scope==='vehicle'?effectivePreferences(state,v):state.preferences;return selectField('Applies to','preferenceScope',[['global','Global defaults for all vehicles'],...(v?[['vehicle','Selected vehicle override']]:[])],scope,'id="preference-scope"')+'<form id="preferences-form" class="form-grid" data-unit="'+unit+'" data-original-km="'+prefs.advanceKm+'" data-original-text="'+distanceText(prefs.advanceKm,unit)+'">'+formField('Advance notice (days)','advanceDays',prefs.advanceDays,'number','min="0" max="365" step="1" required')+formField('Advance distance ('+unit+')','advanceDistance',distanceText(prefs.advanceKm,unit),'number','min="0" step="any" required')+formField('Mileage becomes stale after (days)','staleDays',prefs.staleDays,'number','min="1" max="365" step="1" required')+'<p class="form-note full">'+(v?'Displayed in '+unit+' for '+esc(v.nickname||v.model)+'. ':'No vehicle selected; displayed in km. ')+'Global defaults apply to all vehicles. A vehicle override affects this vehicle only; task overrides take precedence. Existing saved override values are preserved.</p><p class="form-error full" role="alert"></p><button class="button full" type="submit">Save '+(scope==='vehicle'?'vehicle override':'global defaults')+'</button></form>';}
function bindPreferences(){const form=$('#preferences-form');if(!form)return;$('#preference-scope').onchange=e=>{const holder=document.createElement('div');holder.innerHTML=preferencesForm(e.target.value);const oldSelect=$('#preference-scope').closest('label');oldSelect.replaceWith(...holder.childNodes);form.remove();bindPreferences();};form.onsubmit=async e=>{e.preventDefault();try{const f=new FormData(form),values={advanceDays:Number(f.get('advanceDays')),advanceKm:distanceFromInput(f.get('advanceDistance'),form.dataset.unit,Number(form.dataset.originalKm),form.dataset.originalText),staleDays:Number(f.get('staleDays'))};const scope=$('#preference-scope').value;await commit(savePreferences(state,scope==='vehicle'?selected()?.id:null,values));render();}catch(err){form.querySelector('.form-error').textContent=err.message;}};}

function verificationPage(){return '<div class="landing"><a href="#home" class="brand"><img src="'+BRAND.logo+'" alt="VD">VenusDrive</a></div><main id="main" class="auth"><section class="card"><div class="eyebrow">EMAIL VERIFICATION</div><h1>Verify your email.</h1><p>Open the verification link from your account email. You can request another link below.</p>'+(!configured()?'<div class="notice warning">Cloud accounts are not available in this installation. Verification emails cannot be requested yet.</div>':'')+'<form id="auth-form">'+formField('Account email','email','','email','required autocomplete="email"')+'<p class="form-error" role="alert"></p><button class="button" type="submit" '+(!configured()?'disabled':'')+'>Request verification link</button><p id="auth-result" class="form-note" role="status"></p></form></section><nav><a href="#signin">Sign in</a><a href="#signup">Create account</a></nav></main>';}

function remindersPage(){const v=selected();if(!v)return heading('A little notice. A clearer plan.','Add a vehicle to configure reminders.')+emptyVehicle();return heading('Your reminders. Your routine.','Mileage-based reminders depend on you updating your mileage. Snoozing changes notifications, not due thresholds.')+'<div class="reminders-grid"><div>'+reminderPanel(v)+'<section class="card spaced"><h2>Maintenance status</h2>'+taskRows(v)+'</section></div><section class="card"><h2>Advance notice</h2>'+preferencesForm()+'<p class="form-note spaced">In-app reminders only. Email and push delivery are not configured.</p></section></div>';}
function helpPage(){return heading('A clearer way forward.','Practical help for using your garage.')+'<div class="help-grid"><section class="card">'+helpContent()+'</section><section class="card"><h2>Help &amp; Feedback</h2><p>No support delivery channel is configured. Prepare a note to keep or share yourself.</p>'+feedbackForm()+'<p><a href="#privacy">Privacy</a> · <a href="#terms">Use and safety notes</a></p></section></div>';}
function bindFeedback(){const f=$('#feedback-form');if(!f)return;const input=f.elements.feedback,error=$('#feedback-error');const clearError=()=>{if(input.value.trim()){error.hidden=true;error.textContent='';input.removeAttribute('aria-invalid');}};input.addEventListener('input',clearError);f.onsubmit=e=>{e.preventDefault();const note=input.value.trim();if(!note){error.hidden=false;error.textContent='Enter a short note before downloading.';input.setAttribute('aria-invalid','true');input.focus();$('#feedback-status').textContent='';return;}error.hidden=true;input.removeAttribute('aria-invalid');download('VenusDrive feedback\n\n'+note,'VenusDrive-feedback.txt','text/plain');$('#feedback-status').textContent='Feedback note downloaded to this device. It was not submitted or sent to support.';};}
